fn model_gateway_sse() -> String {
    read(&gateway_file("../../../../Model Plane/rust/services/model-gateway/src/sse.rs"))
}

/// The text inside the list literal of `const NAME ... = &[ ... ]` in sse.rs.
fn gateway_list(name: &str) -> String {
    let source = model_gateway_sse();
    let at = source.find(&format!("const {name}")).unwrap_or_else(|| panic!("const {name} not found in model-gateway sse.rs"));
    let literal = &source[source[at..].find("= &[").expect("list literal") + at + 3..];
    delimited(literal, "[", '[', ']').to_owned()
}

fn status_of(name: &str) -> u16 {
    match name {
        "BAD_REQUEST" => 400,
        "UNAUTHORIZED" => 401,
        "NOT_FOUND" => 404,
        "CONFLICT" => 409,
        "SERVICE_UNAVAILABLE" => 503,
        other => panic!("unmapped StatusCode::{other}; extend status_of"),
    }
}

fn gateway_http_refusals() -> Vec<(String, u16)> {
    let list = gateway_list("CONTINUE_HTTP_REFUSALS");
    let mut out = Vec::new();
    let mut rest = list.as_str();
    while let Some(open) = rest.find('(') {
        let entry = delimited(&rest[open..], "(", '(', ')');
        let code = string_literals(entry, '"').into_iter().next().expect("code");
        let status = entry.split("StatusCode::").nth(1).expect("status").split(|c: char| !c.is_ascii_uppercase() && c != '_').next().unwrap();
        out.push((code, status_of(status)));
        rest = &rest[open + 1 + entry.len() + 1..];
    }
    out
}

fn gateway_frame_refusals() -> Vec<String> {
    gateway_list("CONTINUE_FRAME_REFUSALS").lines().map(str::trim).filter(|l| !l.starts_with("//")).flat_map(|l| string_literals(l, '"')).collect()
}

fn spa_frame_refusals() -> Vec<String> {
    let source = spa_contract_source();
    let list = delimited(&source, "export const CHAT_RUN_CONTINUE_FRAME_REFUSALS", '[', ']');
    list.lines().map(str::trim).filter(|l| !l.starts_with("//")).flat_map(|l| string_literals(l, '\'')).collect()
}

#[test]
fn the_bff_list_is_a_subset_of_the_gateway_list_and_the_difference_is_exactly_two_codes() {
    let gateway = gateway_http_refusals();
    assert_eq!(gateway.len(), 10, "{gateway:?}");
    let bff = bff_relayed();
    for pair in &bff {
        assert!(gateway.contains(pair), "the BFF relays {pair:?} which the gateway does not list");
    }
    let mut missing: Vec<&str> = gateway.iter().filter(|p| !bff.contains(p)).map(|p| p.0.as_str()).collect();
    missing.sort_unstable();
    assert_eq!(missing, vec!["continue_incomplete", "missing_bearer"]);
}

#[test]
fn the_gateway_frame_list_is_the_spa_frame_tuple() {
    let mut gateway = gateway_frame_refusals();
    let mut spa = spa_frame_refusals();
    assert_eq!(gateway.len(), 22, "{gateway:?}");
    gateway.sort();
    spa.sort();
    assert_eq!(gateway, spa, "CONTINUE_FRAME_REFUSALS (model-gateway) and CHAT_RUN_CONTINUE_FRAME_REFUSALS (SPA) must be the same set");
}
